(2660604, 369078, 17272, '<td valign="top">Moreso blue and black, but I love the long exposure effect on the waves.</td>', 'Moreso blue and black, but I love the long exposure effect on the waves.', '2006-07-26 01:53:44.000000', NULL, 1),
(2660606, 368179, 17272, '<td valign="top">Out of focus.</td>', 'Out of focus.', '2006-07-26 01:53:57.000000', NULL, 1),
