(2660622, 369277, 39880, '<td valign="top">This one looks familiar.  Again, very nice.  Definitely has that gray scale look to it.  Well done.</td>', 'This one looks familiar.  Again, very nice.  Definitely has that gray scale look to it.  Well done.', '2006-07-26 01:55:41.000000', NULL, 1),
(2660627, 369338, 17272, '<td valign="top">They definitely feel like it!</td>', 'They definitely feel like it!', '2006-07-26 01:55:57.000000', NULL, 1),
