(2668681, 369050, 52500, '<td valign="top">Nice timing!  Great composition.  There are all kinds of cool things to look at throughout the photo.</td>', 'Nice timing!  Great composition.  There are all kinds of cool things to look at throughout the photo.', '2006-07-27 17:16:31.000000', NULL, 1),
(2668685, 369624, 62903, '<td valign="top">There is just something so peacefully in pictures of cats sleeping.</td>', 'There is just something so peacefully in pictures of cats sleeping.', '2006-07-27 17:17:05.000000', NULL, 1),
(2668686, 367259, 30028, '<td valign="top">nice focus!</td>', 'nice focus!', '2006-07-27 17:17:08.000000', NULL, 1),
(2668689, 369159, 52500, '<td valign="top">Looks to be so full it''s overflowing to me!  Great concept and execution (except that the focus seems a bit soft).  I like it!</td>', 'Looks to be so full it''s overflowing to me!  Great concept and execution (except that the focus seems a bit soft).  I like it!', '2006-07-27 17:17:42.000000', NULL, 1),
