(2668910, 369301, 52500, '<td valign="top">Ah...the ol'' coffee and a smoke.  Looks tasty!</td>', 'Ah...the ol'' coffee and a smoke.  Looks tasty!', '2006-07-27 18:07:56.000000', NULL, 1),
(2668949, 367879, 52500, '<td valign="top">That is a sweet looking car.  Nice angle.</td>', 'That is a sweet looking car.  Nice angle.', '2006-07-27 18:17:53.000000', NULL, 1),
(2668953, 367207, 55956, '<td valign="top">I think that when you use this image you can choose between two choices, the first is the symmetrical aspect of the shot and the second is the perspective. Here you have a flat image without symmetri.</td>', 'I think that when you use this image you can choose between two choices, the first is the symmetrical aspect of the shot and the second is the perspective. Here you have a flat image without symmetri.', '2006-07-27 18:18:42.000000', NULL, 1),
(2668954, 368958, 52500, '<td valign="top">Man, I bet this took a lot of work.  Maybe too much, it seems kinda busy.  Cool idea, though, and it''s pretty cool.</td>', 'Man, I bet this took a lot of work.  Maybe too much, it seems kinda busy.  Cool idea, though, and it''s pretty cool.', '2006-07-27 18:19:02.000000', NULL, 1),
(2668955, 369779, 55956, '<td valign="top">too much confused.</td>', 'too much confused.', '2006-07-27 18:19:09.000000', NULL, 1),
