(2673521, 368958, 52731, '<td valign="top">We have the technology. Cute!</td>', 'We have the technology. Cute!', '2006-07-29 09:13:22.000000', NULL, 1),
(2673524, 369404, 52731, '<td valign="top">I am so envious that you had the opportunity to take this photo, I really want to see a real, live elephant for myself one day. This is gorgeous, and I love the emotion captured as well as the texture. Adding to my favorites, good luck with the challenge!</td>', 'I am so envious that you had the opportunity to take this photo, I really want to see a real, live elephant for myself one day. This is gorgeous, and I love the emotion captured as well as the texture. Adding to my favorites, good luck with the challenge!', '2006-07-29 09:14:53.000000', NULL, 1),
(2673529, 369415, 53147, '<td valign="top">Hey - I knew I missed a shot in between opening day and when I voted. I am guessing you were revived from the DQ bin. To be honest I thought this was gonna go that route because of the lack of color in the cats eyes. Makes one think that it was a desat job. But since it has returned you must have gotten by on your editing. That said - I am not quite sure what to think about the processing. Look slike you added film grain maybe to take away from the softness of the shot. The high contrast at first seemed too much but as I sit and go back and look at it again and again I seem to enjoy the pic more. I really like cat pics in the first place and thi sone is growing on me. I hope the time away from voters hasnt hurt you too much. Good luck!</td>', 'Hey - I knew I missed a shot in between opening day and when I voted. I am guessing you were revived from the DQ bin. To be honest I thought this was gonna go that route because of the lack of color in the cats eyes. Makes one think that it was a desat job. But since it has returned you must have gotten by on your editing. That said - I am not quite sure what to think about the processing. Look slike you added film grain maybe to take away from the softness of the shot. The high contrast at first seemed too much but as I sit and go back and look at it again and again I seem to enjoy the pic more. I really like cat pics in the first place and thi sone is growing on me. I hope the time away from voters hasnt hurt you too much. Good luck!', '2006-07-29 09:21:35.000000', NULL, 1),
(2673533, 366471, 61267, '<td valign="top">Cropping and a deeper DOF would really have helped this shot out. The upper right part of your photo really does nothing for the image.</td>', 'Cropping and a deeper DOF would really have helped this shot out. The upper right part of your photo really does nothing for the image.', '2006-07-29 09:24:44.000000', NULL, 1),
(2673547, 368495, 61267, '<td valign="top">There doesn''t seem to be enough contrast between the black and white...seems alittle dull. I do like the idea for your shot though.</td>', 'There doesn''t seem to be enough contrast between the black and white...seems alittle dull. I do like the idea for your shot though.', '2006-07-29 09:30:12.000000', NULL, 1),
(2673593, 369649, 61215, '<td valign="top">Totally stunning photo. Is this in Iceland? I was there last year and think I remember that scene. Really good image, and I love the tones. 10/10</td>', 'Totally stunning photo. Is this in Iceland? I was there last year and think I remember that scene. Really good image, and I love the tones. 10/10', '2006-07-29 10:04:36.000000', NULL, 1),
(2673658, 369413, 60174, '<td valign="top">could be sharper, but I like the composition and the idea.</td>', 'could be sharper, but I like the composition and the idea.', '2006-07-29 10:33:56.000000', NULL, 1),
