INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2675028, 369773, 35994, '<td valign="top">love it, the reflections are great. great idea!!</td>', 'love it, the reflections are great. great idea!!', '2006-07-29 23:18:08.000000', NULL, 1),
