(2675039, 366683, 62493, '<td valign="top">I like the design of the picture, but the double image of the reflection detracts from the impact of teh picture a bit.</td>', 'I like the design of the picture, but the double image of the reflection detracts from the impact of teh picture a bit.', '2006-07-29 23:23:08.000000', NULL, 1),
(2675040, 367691, 35994, '<td valign="top">i could see this being a poster, nice shot :)</td>', 'i could see this being a poster, nice shot :)', '2006-07-29 23:23:09.000000', NULL, 1),
(2675041, 367949, 62493, '<td valign="top">Clever, and fun. A different pose would be more effective, I think, but a fun and cool idea :)</td>', 'Clever, and fun. A different pose would be more effective, I think, but a fun and cool idea :)', '2006-07-29 23:24:37.000000', NULL, 1),
