(2675109, 368110, 45790, '<td valign="top">Wonderful minimalist shot.</td>', 'Wonderful minimalist shot.', '2006-07-29 23:50:20.000000', NULL, 1),
(2675110, 366972, 45790, '<td valign="top">Nicely composed abstract.</td>', 'Nicely composed abstract.', '2006-07-29 23:50:34.000000', NULL, 1),
(2675111, 369816, 45790, '<td valign="top">A very pleasing abstract.</td>', 'A very pleasing abstract.', '2006-07-29 23:50:42.000000', NULL, 1),
